// src/pages/TermsAndConditions.jsx
import React, { useState, useMemo } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import NavBar from "../NavBar.jsx";
import BottomNav from "../components/BottomNav.jsx";

const TermsAndConditions = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const selectedTech = location.state?.selectedTech || 'Unknown';

  // Checkboxes for rules
  const [checkboxes, setCheckboxes] = useState({
    attire: false,
    grooming: false,
    greeting: false,
    engagement: false,
    verbalCommunication: false,
    nonVerbalCommunication: false,
    professionalism: false,
    confidence: false,
  });

  // Accessibility: let user skip greeting/eye-contact evaluation
  const [skipFaceCues, setSkipFaceCues] = useState(false);
  const [accessibilityNote, setAccessibilityNote] = useState("");

  const isRuleDisabled = (key) =>
    skipFaceCues && (key === 'greeting' || key === 'engagement');

  const handleCheckboxChange = (key) => {
    if (isRuleDisabled(key)) return; // ignore changes if disabled by accessibility
    setCheckboxes((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  // Only require non-disabled rules to be checked
  const allChecked = useMemo(() => {
    const requiredKeys = Object.keys(checkboxes).filter((k) => !isRuleDisabled(k));
    return requiredKeys.every((k) => checkboxes[k]);
  }, [checkboxes, skipFaceCues]);

  const handleProceed = () => {
    if (!allChecked) return;
    navigate('/resume-upload', {
      state: {
        selectedTech,
        accessibility: {
          skipGreetingAndEngagement: skipFaceCues,
          note: accessibilityNote?.trim() || null,
        },
      },
    });
  };

  const rules = [
    {
      key: 'attire',
      title: 'Attire',
      description:
        'Wear clean, ironed, and professional clothes (e.g., shirt for men, kurti for women), ensuring cleanliness, appropriate fit, and polished presentation.',
      imageAlt: 'Neatly dressed person',
    },
    {
      key: 'grooming',
      title: 'Grooming',
      description:
        'Maintain neat hair, trimmed facial hair (if any), and good hygiene, with minimal accessories for a professional appearance.',
      imageAlt: 'Person with neat hair and grooming',
    },
    {
      key: 'greeting',
      title: 'Greeting',
      description:
        'Deliver a clear greeting (e.g., "Good morning") with a confident and poised entry, immediate awareness, and a genuine smile.',
      imageAlt: 'Smiling person greeting',
    },
    {
      key: 'engagement',
      title: 'Engagement',
      description:
        'Maintain steady eye contact and proper seating posture to demonstrate engagement and confidence during the interview.',
      imageAlt: 'Person sitting with steady eye contact',
    },
    {
      key: 'verbalCommunication',
      title: 'Verbal Communication',
      description:
        'Speak clearly and confidently with minimal filler words (e.g., "um," "uh"), ensuring clarity, appropriate volume, and steady pace.',
      imageAlt: 'Person speaking confidently',
    },
    {
      key: 'nonVerbalCommunication',
      title: 'Non-Verbal Communication',
      description:
        'Use open posture, natural gestures, and engaged facial expressions to convey enthusiasm and professionalism.',
      imageAlt: 'Person with open posture and gestures',
    },
    {
      key: 'professionalism',
      title: 'Professionalism',
      description:
        'Exhibit respectful, prepared, and positive behavior, combining respect, humility, punctuality, and a positive demeanor.',
      imageAlt: 'Person behaving respectfully',
    },
    {
      key: 'confidence',
      title: 'Confidence',
      description:
        'Present your skills with assurance and articulate self-advocacy, justifying your resume with confidence.',
      imageAlt: 'Person presenting skills confidently',
    },
  ];

  return (
    <div className="bg-gradient-to-b from-gray-900 to-gray-800 text-white min-h-screen pb-32">
      <NavBar />
      <div className="pt-20 p-6 max-w-4xl mx-auto">
        <h1 className="text-4xl font-bold mb-2 text-center text-blue-400">Terms and Conditions</h1>
        <p className="text-center mb-8 text-gray-300">Selected Technology: {selectedTech}</p>

        {/* Accessibility & Inclusion */}
        <div className="bg-gray-800 rounded-lg p-4 shadow-lg mb-8">
          <h2 className="text-xl font-semibold text-blue-300 mb-2">Accessibility &amp; Inclusion</h2>
          <p className="text-gray-300 text-sm mb-3">
            If you have a facial mobility/appearance difference (e.g., limited head movement, atypical eye alignment, or similar)
            that could affect <b>greeting</b> or <b>eye contact</b> on camera, you can opt to skip evaluation for those two items.
            This helps the avatar interpret your behavior fairly. (We only use this during the interview and don’t store it long-term.)
          </p>

          <label className="flex items-start gap-3">
            <input
              type="checkbox"
              checked={skipFaceCues}
              onChange={() => setSkipFaceCues(v => !v)}
              className="mt-1 h-5 w-5 text-blue-500 rounded focus:ring-blue-400"
            />
            <span className="text-gray-200">
              Yes — please <b>skip evaluating “Greeting” and “Engagement (eye contact/posture)”</b> for accessibility.
              {skipFaceCues && (
                <span className="ml-2 inline-block align-middle text-amber-300 text-xs bg-amber-500/10 rounded px-2 py-0.5">
                  2 rules will be skipped
                </span>
              )}
            </span>
          </label>

          {skipFaceCues && (
            <div className="mt-3">
              <label className="block text-sm text-gray-300 mb-1" htmlFor="accessibility-note">
                Optional note for the avatar (max 120 chars)
              </label>
              <input
                id="accessibility-note"
                type="text"
                maxLength={120}
                value={accessibilityNote}
                onChange={(e) => setAccessibilityNote(e.target.value)}
                placeholder="e.g., I can’t turn my head fully to the left; eye contact may look different."
                className="w-full h-11 px-4 rounded-xl bg-gray-900 text-gray-100 placeholder-gray-500 ring-1 ring-gray-700 focus:ring-2 focus:ring-sky-400/60 focus:outline-none"
              />
            </div>
          )}
        </div>

        {/* Rules Section */}
        <h2 className="text-2xl font-semibold mb-6 text-center text-blue-300">Interview Rules</h2>
        <p className="text-center mb-8 text-gray-300">
          Please review and agree to the following rules to proceed with the FresherLaunch mock interview.
        </p>
        {!allChecked && (
          <p className="text-red-500 text-sm mb-4 text-center">
            Please check all required boxes{skipFaceCues ? ' (2 rules are skipped for accessibility)' : ''}.
          </p>
        )}

        <div className="bg-gray-800 rounded-lg p-4 shadow-lg">
          <div className="space-y-4">
            {rules.map((rule, index) => {
              const disabled = isRuleDisabled(rule.key);
              return (
                <div
                  key={rule.key}
                  className={`flex items-start ${disabled ? 'opacity-60' : ''}`}
                >
                  {/* Image Placeholder */}
                  <div className="flex-shrink-0 w-16 h-16 bg-gray-600 rounded-md mr-4 flex items-center justify-center">
                    <p className="text-xs text-gray-300 text-center">{rule.imageAlt}</p>
                  </div>

                  {/* Rule Description and Checkbox */}
                  <div className="flex-1">
                    <h3 className="text-lg font-semibold text-blue-300">
                      {index + 1}. {rule.title}{' '}
                      {disabled && (
                        <span className="ml-2 text-xs text-amber-300 bg-amber-500/10 px-2 py-0.5 rounded">
                          Skipped (accessibility)
                        </span>
                      )}
                    </h3>
                    <p className="text-gray-300 mb-2">{rule.description}</p>

                    <label className={`flex items-center ${disabled ? 'pointer-events-none' : ''}`}>
                      <input
                        type="checkbox"
                        disabled={disabled}
                        checked={checkboxes[rule.key]}
                        onChange={() => handleCheckboxChange(rule.key)}
                        className="h-5 w-5 text-blue-500 rounded focus:ring-blue-400 disabled:opacity-40"
                        aria-describedby={`${rule.key}-description`}
                      />
                      <span className="ml-2 text-gray-300">
                        {disabled ? 'This rule is skipped due to accessibility preference' : 'I agree to follow this rule'}
                      </span>
                    </label>
                    <p id={`${rule.key}-description`} className="sr-only">
                      {rule.description}
                    </p>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Proceed Button */}
        <button
          onClick={handleProceed}
          disabled={!allChecked}
          className={`w-full mt-8 py-2 px-4 rounded font-bold text-white transition duration-300 ${
            allChecked ? 'bg-green-500 hover:bg-green-600' : 'bg-gray-500 cursor-not-allowed'
          }`}
        >
          Proceed to next step
        </button>
      </div>

      {/* Sticky Footer Bar */}
      <BottomNav />
    </div>
  );
};

export default TermsAndConditions;
